package com.procurement.vendorquotation.controller;import com.procurement.common.response.*;import com.procurement.vendorquotation.dto.request.*;import com.procurement.vendorquotation.dto.response.*;import com.procurement.vendorquotation.service.*;import jakarta.validation.Valid;import org.springframework.data.domain.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;@RestController@RequestMapping("/api/vendor-quotation-lines")public class VendorQuotationLineController{private final VendorQuotationService service;public VendorQuotationLineController(VendorQuotationService s){service=s;}private Pageable p(int a,int b,String c,String d){return PageRequest.of(a,b,Sort.by(Sort.Direction.fromString(d),c));}@PostMapping public ResponseEntity<ApiResponse<VendorQuotationLineResponse>>create(@Valid@RequestBody VendorQuotationLineRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(ApiResponse.success("Quotation line created",service.addLine(r)));}@GetMapping public ApiResponse<PageResponse<VendorQuotationLineResponse>>search(@RequestParam(required=false)Long quotationId,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size,@RequestParam(defaultValue="id")String sort,@RequestParam(defaultValue="asc")String direction){return ApiResponse.success(service.lines(quotationId,p(page,size,sort,direction)));}@GetMapping("/search")public ApiResponse<PageResponse<VendorQuotationLineResponse>>searchAlias(@RequestParam(required=false)Long quotationId,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size,@RequestParam(defaultValue="id")String sort,@RequestParam(defaultValue="asc")String direction){return search(quotationId,page,size,sort,direction);}@GetMapping("/{id}")public ApiResponse<VendorQuotationLineResponse>get(@PathVariable Long id){return ApiResponse.success(service.getLine(id));}@PutMapping("/{id}")public ApiResponse<VendorQuotationLineResponse>update(@PathVariable Long id,@Valid@RequestBody VendorQuotationLineRequest r){return ApiResponse.success("Quotation line updated",service.updateLine(id,r));}@DeleteMapping("/{id}")public ResponseEntity<Void>delete(@PathVariable Long id){service.deleteLine(id);return ResponseEntity.noContent().build();}}
